class Animal {
    void ownerComesHome() {
        System.out.println("Animal welcomes the owner");
    }
}

class Dog extends Animal {
    @Override
    void ownerComesHome() {
        System.out.println(“Dog welcomes by jumping, spinning, and                revolving around the owner");
    }
}

class Cat extends Animal {
    @Override
    void ownerComesHome() {
        System.out.println("Cat welcomes by sleeping");
    }
}

class Parrot extends Animal {
    @Override
    void ownerComesHome() {
        System.out.println("Parrot welcomes by screaming");
    }
}

Dog d = new Dog();
Cat c = new Cat();
Parrot p = new Parrot();

